export function normalizeLanguage(code){
  if(code==='ko') return 'ko-KR';
  if(code==='en') return 'en-US';
  return supportedLanguages.some(x=>x.code===code) ? code : 'en-US';
}

export function tOption(lang, group, key){
  const l=normalizeLanguage(lang);
  return EXTRA_OPTIONS[l]?.[group]?.[key] ?? O[l]?.[group]?.[key] ?? EXTRA_OPTIONS['en-US']?.[group]?.[key] ?? O['en-US']?.[group]?.[key] ?? key;
}

export function tUI(lang, key){
  const l=normalizeLanguage(lang);
  return EXTRA_UI[l]?.[key] ?? UI[l]?.[key] ?? EXTRA_UI['en-US']?.[key] ?? UI['en-US']?.[key] ?? key;
}

export function languageLabel(code){
  const l=normalizeLanguage(code);
  return supportedLanguages.find(x=>x.code===l)?.label ?? l;
}
